 <?php if(!empty($aguardandoRecebimento)):foreach($aguardandoRecebimento as $item):$pedidoEntrega=$item['pedido']??[];$lojaEntrega=trim((string)($pedidoEntrega['cliente_nome_fantasia']??''))?:trim((string)($pedidoEntrega['cliente_razao_social']??''));$dataEntrega=!empty($item['data_expedicao'])?strtotime((string)$item['data_expedicao']):false;?>
 <tr><td><strong><?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?></strong></td><td><span class="entrega-loja" title="<?= $esc($lojaEntrega); ?>"><?= $esc($lojaEntrega?:'Loja não identificada'); ?></span></td><td><?= $esc($item['romaneio']??'—'); ?></td><td><?= (int)($item['volumes']??1); ?></td><td><?php if($dataEntrega):?><span class="expedicao-date"><strong><?= date('Y-m-d',$dataEntrega); ?></strong><small><?= date('H:i:s',$dataEntrega); ?></small></span><?php else:?>—<?php endif;?></td><td><span class="entrega-status"><svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>Expedido</span></td><td><button type="button" class="button button-primary" data-entrega-id="<?= (int)$item['id']; ?>" data-entrega-pedido="<?= $esc($pedidoEntrega['codigo']??'#'.($pedidoEntrega['id']??0)); ?>">Entregar</button></td></tr>
 <?php endforeach;else:?><tr><td colspan="7" class="expedicao-empty">Nenhuma entrega própria aguardando confirmação.</td></tr><?php endif;?></tbody></table></div>
