<div class="entrega-modal" data-entrega-modal hidden><div class="entrega-backdrop" data-entrega-close></div><section class="entrega-dialog" role="dialog" aria-modal="true"><header><div><h3>Confirmar entrega</h3><p>Pedido <strong data-entrega-label></strong></p></div><button type="button" class="entrega-close" data-entrega-close>×</button></header><form class="entrega-form" data-base-action="<?= $esc($url('expedicao/recebimento')); ?>"><input type="hidden" name="expedicao_id"><label>Nome do recebedor<input type="text" name="recebedor_nome" maxlength="120" required placeholder="Nome de quem recebeu"></label><label>Assinatura do recebedor<span class="entrega-pad"><svg data-entrega-svg viewBox="0 0 900 270" preserveAspectRatio="none"></svg><i></i><button type="button" class="button button-outline" data-entrega-clear>Limpar</button></span><input type="hidden" name="assinatura_recebedor"></label><footer><button type="button" class="button button-outline" data-entrega-close>Cancelar</button><button type="submit" class="button button-primary" data-entrega-submit>Confirmar entrega</button></footer></form></section></div>
<style>
.entrega-table th,.entrega-table td{text-align:center!important;vertical-align:middle!important}.entrega-table th{font-size:10.6px!important}.entrega-table td{font-size:13px!important;white-space:nowrap}.entrega-table :is(th,td):nth-child(2){width:170px;max-width:170px}.entrega-table td:nth-child(2){white-space:normal}.entrega-loja{display:-webkit-box;height:32px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2;line-height:16px;overflow-wrap:anywhere}.entrega-status{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;background:#e0f2fe;color:#0369a1;font-size:12px;font-weight:850}.entrega-status svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.1}.entrega-modal{position:fixed;z-index:10020;inset:0;display:grid;place-items:center;padding:16px}.entrega-modal[hidden]{display:none}.entrega-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.68);backdrop-filter:blur(4px)}.entrega-dialog{position:relative;width:min(650px,100%);padding:28px;border-radius:24px;background:#fff;box-shadow:0 28px 80px rgba(15,23,42,.3)}.entrega-dialog header{display:flex;justify-content:space-between;margin-bottom:20px}.entrega-dialog h3{margin:0 0 4px}.entrega-dialog p{margin:0;color:var(--text-muted)}.entrega-close{width:36px;height:36px;border:0;border-radius:11px;background:var(--surface-muted);font-size:24px}.entrega-form{display:grid;gap:17px}.entrega-form label{display:grid;gap:8px;font-weight:800}.entrega-form input[type=text]{min-height:50px;padding:0 14px;border:1px solid var(--border);border-radius:13px;font:inherit}.entrega-pad{position:relative;display:block;height:220px;overflow:hidden;border:1px dashed color-mix(in srgb,var(--primary) 55%,var(--border));border-radius:15px;background:#fff}.entrega-pad.has-ink{border-color:var(--primary)}.entrega-pad>svg{position:absolute;z-index:2;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.entrega-pad>i{position:absolute;z-index:1;left:9%;right:9%;bottom:28%;height:1px;background:#94a3b8}.entrega-pad>[data-entrega-clear]{position:absolute;z-index:3;right:9px;top:9px;min-height:36px!important;padding:6px 11px!important}.entrega-form footer{display:flex;justify-content:flex-end;gap:10px}.entrega-form footer .button{min-height:46px;justify-content:center}@media(max-width:600px){.entrega-dialog{padding:20px}.entrega-pad{height:190px}.entrega-form footer{display:grid;grid-template-columns:1fr 1fr}}
</style>
<script>
(()=>{const modal=document.querySelector('[data-entrega-modal]'),form=modal?.querySelector('.entrega-form'),svg=form?.querySelector('[data-entrega-svg]'),pad=form?.querySelector('.entrega-pad'),hidden=form?.elements.assinatura_recebedor,submit=form?.querySelector('[data-entrega-submit]');if(!modal||!form||!svg||!pad||!hidden||!submit)return;let active=false,path=null,hasInk=false;const point=e=>{const r=svg.getBoundingClientRect();return{x:(e.clientX-r.left)*900/r.width,y:(e.clientY-r.top)*270/r.height}};const start=e=>{e.preventDefault();active=true;hasInk=true;const p=point(e);path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${p.x} ${p.y}`);path.setAttribute('fill','none');path.setAttribute('stroke','#111827');path.setAttribute('stroke-width','4');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');svg.appendChild(path);svg.setPointerCapture?.(e.pointerId);pad.classList.add('has-ink')};const move=e=>{if(!active||!path)return;e.preventDefault();const p=point(e);path.setAttribute('d',`${path.getAttribute('d')} L${p.x} ${p.y}`)};const end=()=>{active=false;path=null};svg.addEventListener('pointerdown',start);svg.addEventListener('pointermove',move);window.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);const clear=()=>{svg.replaceChildren();hidden.value='';active=false;path=null;hasInk=false;pad.classList.remove('has-ink')};form.querySelector('[data-entrega-clear]').addEventListener('click',clear);const close=()=>{modal.hidden=true;document.body.style.overflow='';form.reset();clear()};document.querySelectorAll('[data-entrega-close]').forEach(b=>b.addEventListener('click',close));document.querySelectorAll('[data-entrega-id]').forEach(b=>b.addEventListener('click',()=>{clear();form.action=`${form.dataset.baseAction}/${encodeURIComponent(b.dataset.entregaId)}`;form.elements.expedicao_id.value=b.dataset.entregaId;modal.querySelector('[data-entrega-label]').textContent=b.dataset.entregaPedido||'';modal.hidden=false;document.body.style.overflow='hidden';form.elements.recebedor_nome.focus()}));const png=()=>new Promise((resolve,reject)=>{if(!hasInk){reject(new Error('Faça a assinatura do recebedor.'));return}const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','900');clone.setAttribute('height','270');const source=`data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(new XMLSerializer().serializeToString(clone))))}`,image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=900;canvas.height=270;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);resolve(canvas.toDataURL('image/png'))};image.onerror=()=>reject(new Error('Não foi possível processar a assinatura.'));image.src=source});form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.saving==='1')return;try{hidden.value=await png();form.dataset.saving='1';submit.disabled=true;const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível salvar a entrega.');window.showAppToast?.('Assinatura salva com sucesso.','success');setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){window.showAppToast?.(error.message||'Não foi possível salvar a entrega.','error')}finally{delete form.dataset.saving;submit.disabled=false}},true)})();
</script>
<script>(()=>{const form=document.querySelector('.entrega-form'),pad=form?.querySelector('.entrega-pad'),svg=form?.querySelector('[data-entrega-svg]'),hidden=form?.elements.assinatura_recebedor,submit=form?.querySelector('[data-entrega-submit]');if(!form||!pad||!svg||!hidden||!submit)return;let ativo=false,assinou=false,caminho=null;const ponto=(x,y)=>{const r=svg.getBoundingClientRect();return{x:(x-r.left)*900/r.width,y:(y-r.top)*270/r.height}};const iniciar=(x,y,event)=>{if(event.target.closest?.('[data-entrega-clear]'))return;event.preventDefault();ativo=true;assinou=true;const p=ponto(x,y);caminho=document.createElementNS('http://www.w3.org/2000/svg','path');caminho.setAttribute('d',`M${p.x} ${p.y} l.5 .5`);caminho.setAttribute('fill','none');caminho.setAttribute('stroke','#111827');caminho.setAttribute('stroke-width','4');caminho.setAttribute('stroke-linecap','round');caminho.setAttribute('stroke-linejoin','round');svg.appendChild(caminho);pad.classList.add('has-ink')};const mover=(x,y,event)=>{if(!ativo||!caminho)return;event.preventDefault();const p=ponto(x,y);caminho.setAttribute('d',`${caminho.getAttribute('d')} L${p.x} ${p.y}`)};const terminar=()=>{ativo=false;caminho=null};pad.addEventListener('pointerdown',event=>iniciar(event.clientX,event.clientY,event),true);window.addEventListener('pointermove',event=>mover(event.clientX,event.clientY,event),true);window.addEventListener('pointerup',terminar,true);pad.addEventListener('touchstart',event=>{if(window.PointerEvent)return;const t=event.touches[0];if(t)iniciar(t.clientX,t.clientY,event)},{capture:true,passive:false});window.addEventListener('touchmove',event=>{if(window.PointerEvent)return;const t=event.touches[0];if(t)mover(t.clientX,t.clientY,event)},{capture:true,passive:false});window.addEventListener('touchend',terminar,true);form.querySelector('[data-entrega-clear]')?.addEventListener('click',()=>{assinou=false;ativo=false;caminho=null;hidden.value=''},true);const gerarPng=()=>new Promise((resolve,reject)=>{if(!assinou||!svg.querySelector('path')){reject(new Error('Faça a assinatura do recebedor.'));return}const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','900');clone.setAttribute('height','270');const raw=new XMLSerializer().serializeToString(clone),image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=900;canvas.height=270;canvas.getContext('2d').drawImage(image,0,0);resolve(canvas.toDataURL('image/png'))};image.onerror=()=>reject(new Error('Não foi possível processar a assinatura.'));image.src=`data:image/svg+xml;charset=utf-8,${encodeURIComponent(raw)}`});document.addEventListener('submit',async event=>{if(event.target!==form)return;event.preventDefault();event.stopImmediatePropagation();if(form.dataset.forceSaving==='1')return;try{hidden.value=await gerarPng();form.dataset.forceSaving='1';submit.disabled=true;const response=await fetch(form.action,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Não foi possível salvar a entrega.');window.showAppToast?.('Assinatura salva com sucesso.','success');setTimeout(()=>location.assign(`${location.pathname}?tab=concluidos`),350)}catch(error){window.showAppToast?.(error.message||'Não foi possível salvar a entrega.','error')}finally{delete form.dataset.forceSaving;submit.disabled=false}},true)})();</script>
